//! Explicit build-time protocol generation. --check rejects stale committed SDK
//! types without modifying them; ordinary server builds need no TS toolchain.

use server::protocol::{CallError, Event, Request, StructuredCallError};
use ts_rs::{Config, TS};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config = Config::default();
    let generated = format!(
        "// Generated by cargo run -p server --features protocol-codegen --bin export-protocol.\n// Edit packages/server/src/protocol.rs, not this file.\nimport type {{ JsonValue }} from './values';\n\nexport const MAX_WIRE_MESSAGE_BYTES = {};\n\nexport {}\n\nexport {}\n\nexport {}\n\nexport {}\n",
        engine::MAX_WIRE_MESSAGE_BYTES,
        StructuredCallError::decl(&config),
        CallError::decl(&config),
        Request::decl(&config),
        Event::decl(&config)
    );
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../sdk/src/protocol.ts");
    if std::env::args().skip(1).any(|arg| arg == "--check") {
        if std::fs::read_to_string(&path)? != generated {
            return Err("SDK protocol is stale; run export-protocol".into());
        }
    } else {
        std::fs::write(path, generated)?;
    }
    Ok(())
}
